@import '../../../common/style/base.less';

//组合头像偏移量
@avatar-group-offset-small: var(--td-avatar-group-margin-left-small, calc(-1 * @spacer));
@avatar-group-offset-medium: var(--td-avatar-group-margin-left-medium, calc(-1 * @spacer));
@avatar-group-offset-large: var(--td-avatar-group-margin-left-large, calc(-1 * @spacer));
@avatar-group-line-spacing: var(--td-avatar-group-line-spacing, calc(@spacer / 4));

@avatar-group-init-zIndex: 50;

.generate-z-index(@n, @i: 1) when (@i =< @n) {
  & .@{prefix}-avatar__wrapper:nth-child(@{i}) {
    z-index: calc(var(--td-avatar-group-init-z-index, @avatar-group-init-zIndex) - @i);
  }

  .generate-z-index(@n, (@i + 1));
}

.@{prefix}-avatar-group {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;

  &-offset-left,
  &-offset-right {
    & .@{prefix}-avatar__wrapper {
      padding: @avatar-group-line-spacing 0;
    }

    &-small {
      --td-avatar-margin-left: @avatar-group-offset-small; // ‘small’尺寸组合头像偏移间距
    }

    &-medium {
      --td-avatar-margin-left: @avatar-group-offset-medium; // ‘medium’尺寸组合头像偏移间距
    }

    &-large {
      --td-avatar-margin-left: @avatar-group-offset-large; // ‘large’尺寸组合头像偏移间距
    }
  }

  &-offset-left {
    .generate-z-index(@avatar-group-init-zIndex);
  }

  &__collapse--slot,
  &__collapse--default {
    z-index: 0;
    font-weight: 600;
  }

  &__collapse--slot {
    float: left;
  }

  &__collapse--slot:not(:empty) + &__collapse--default {
    display: none;
    float: left;
  }

  &__collapse--slot:empty + &__collapse--default {
    display: block;
    float: left;
  }
}

@import '../../../common/style/base.less';

@avatar-bg-color: var(--td-avatar-bg-color, @brand-color-light-active);
@avatar-content-color: var(--td-avatar-content-color, @brand-color);
@avatar-small-width: var(--td-avatar-small-width, 80rpx);
@avatar-medium-width: var(--td-avatar-medium-width, 96rpx);
@avatar-large-width: var(--td-avatar-large-width, 128rpx);

@avatar-text-small-font-size: var(--td-avatar-text-small-font-size, @font-size-base);
@avatar-text-medium-font-size: var(--td-avatar-text-medium-font-size, @font-size-m);
@avatar-text-large-font-size: var(--td-avatar-text-large-font-size, @font-size-xl);

@avatar-icon-small-font-size: var(--td-avatar-icon-small-font-size, @font-size-xl);
@avatar-icon-medium-font-size: var(--td-avatar-icon-medium-font-size, 48rpx);
@avatar-icon-large-font-size: var(--td-avatar-icon-large-font-size, 64rpx);

@avatar-border-width-small: var(--td-avatar-border-width-small, 2rpx);
@avatar-border-width-medium: var(--td-avatar-border-width-medium, 4rpx);
@avatar-border-width-large: var(--td-avatar-border-width-large, 6rpx);
@avatar-border-color: var(--td-avatar-border-color, #fff);
@avatar-circle-border-radius: var(--td-avatar-circle-border-radius, @radius-circle);
@avatar-round-border-radius: var(--td-avatar-round-border-radius, @radius-default);

@avatar-margin-left: var(--td-avatar-margin-left, 0);

.@{prefix}-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  background-color: @avatar-bg-color;
  color: @avatar-content-color;

  &__wrapper {
    display: inline-flex;
    position: relative;
    vertical-align: top;
    margin-left: @avatar-margin-left;
  }

  &--large {
    width: @avatar-large-width;
    height: @avatar-large-width;
    font-size: @avatar-text-large-font-size;

    .@{prefix}-avatar__icon {
      font-size: @avatar-icon-large-font-size;
    }
  }

  &--medium {
    width: @avatar-medium-width;
    height: @avatar-medium-width;
    font-size: @avatar-text-medium-font-size;

    .@{prefix}-avatar__icon {
      font-size: @avatar-icon-medium-font-size;
    }
  }

  &--small {
    width: @avatar-small-width;
    height: @avatar-small-width;
    font-size: @avatar-text-small-font-size;

    .@{prefix}-avatar__icon {
      font-size: @avatar-icon-small-font-size;
    }
  }

  .@{prefix}-image,
  &__image {
    width: 100%;
    height: 100%;

    &-alt {
      display: flex;
      align-items: center;
      justify-content: center;
      padding: @spacer;
      overflow: hidden;
    }
  }

  &--circle {
    border-radius: @avatar-circle-border-radius;
    overflow: hidden;
  }

  &--round {
    border-radius: @avatar-round-border-radius;
    overflow: hidden;
  }

  &__text,
  &__icon {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    &:empty {
      width: 0;
      height: 0;
    }
  }

  // 头像边框
  &--border {
    border-color: @avatar-border-color;
    border-style: solid;
    &-small {
      border-width: @avatar-border-width-small;
    }

    &-medium {
      border-width: @avatar-border-width-medium;
    }

    &-large {
      border-width: @avatar-border-width-large;
    }
  }
}

@import '../../../common/style/base.less';

@backtop: ~'@{prefix}-back-top';
@back-top-text-font-size: @font-size;
@back-top-text-line-height: 24rpx;
@back-top-icon-size: 44rpx;
@back-top-round-width: 96rpx;
@back-top-half-round-width: 120rpx;
@back-top-half-round-height: 80rpx;
@back-top-fixed-right: @spacer;
@safe-area-inset-bottom: constant(safe-area-inset-bottom);
@safe-area-inset-bottom: env(safe-area-inset-bottom);
@back-top-fixed-bottom: calc(@spacer-2 + @safe-area-inset-bottom);
@back-top-round-color: var(--td-back-top-round-color, @text-color-primary);
@back-top-round-bg-color: var(--td-back-top-round-bg-color, @bg-color-container);
@back-top-round-border-color: var(--td-back-top-round-border-color, @component-border);
@back-top-round-border-radius: var(--td-back-top-round-border-radius, @radius-circle); // 'round'主题圆角大小
@back-top-round-dark-color: var(--td-back-top-round-dark-color, @text-color-anti); // 'round-dark'主题内容颜色
@back-top-round-dark-bg-color: var(--td-back-top-round-dark-bg-color, @gray-color-13); // 'round-dark'主题背景颜色
@back-top-half-round-border-radius: var(
  --td-back-top-half-round-border-radius,
  @radius-round
); // 'round-dark'主题圆角大小

.@{backtop} {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background-color: transparent;
  overflow: hidden;
  box-sizing: border-box;
  transition: height 0.2s;
  height: auto;

  &--fixed {
    position: fixed;
    right: @back-top-fixed-right;
    bottom: @back-top-fixed-bottom;
  }

  &--round,
  &--round-dark {
    width: @back-top-round-width;
    height: @back-top-round-width;
    border-radius: @back-top-round-border-radius;
  }

  &--round,
  &--half-round {
    color: @back-top-round-color;
    border: 1rpx solid @back-top-round-border-color;
    background-color: @back-top-round-bg-color;
  }

  &--round-dark,
  &--half-round-dark {
    color: @back-top-round-dark-color;
    background-color: @back-top-round-dark-bg-color;
  }

  &--half-round,
  &--half-round-dark {
    width: @back-top-half-round-width;
    height: @back-top-half-round-height;
    border-radius: 0;
    border-top-left-radius: @back-top-half-round-border-radius;
    border-bottom-left-radius: @back-top-half-round-border-radius;
    flex-direction: row;
    right: 0;
  }

  &__text--round,
  &__text--round-dark,
  &__text--half-round,
  &__text--half-round-dark {
    font-weight: 600;
    font-size: @back-top-text-font-size;
    line-height: @back-top-text-line-height;
  }

  &__text--half-round,
  &__text--half-round-dark {
    width: 48rpx;
  }

  &__icon:not(:empty) + &__text--half-round,
  &__icon:not(:empty) + &__text--half-round-dark {
    margin-left: calc(@spacer / 2);
  }

  &__icon {
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: @back-top-icon-size;
  }
}

@import '../../../common/style/base.less';

@badge-text-color: var(--td-badge-text-color, @text-color-anti);
@badge-content-text-color: var(--td-badge-content-text-color, @text-color-primary);
@badge-content-text-font: var(--td-badge-content-text-font, @font-body-large);
@badge-color: var(--td-badge-bg-color, @error-color);
@badge-font: var(--td-badge-font, @font-mark-extraSmall);
@badge-basic-height: var(--td-badge-basic-height, 32rpx);
@badge-basic-width: var(--td-badge-basic-width, 32rpx);
@badge-basic-padding: var(--td-badge-basic-padding, calc(@spacer / 2));
@badge-border-radius: var(--td-badge-border-radius, 4rpx);
@border-bubble-border-radius: var(--td-badge-bubble-border-radius, 20rpx 20rpx 20rpx 1px);
@badge-dot-size: var(--td-badge-dot-size, 16rpx);

// large
@badge-large-font: var(--td-badge-large-font, @font-mark-small);
@badge-large-height: var(--td-badge-large-height, 40rpx);
@badge-large-padding: var(--td-badge-large-padding, 10rpx);

.@{prefix}-badge {
  position: relative;
  display: inline-flex;
  align-items: start;

  &--basic {
    z-index: 100;
    padding: 0 @badge-basic-padding;
    font: @badge-font;
    color: @badge-text-color;
    background-color: @badge-color;
    text-align: center;
    height: @badge-basic-height;
    border-radius: @badge-border-radius;
  }

  &--dot {
    height: @badge-dot-size;
    border-radius: @radius-circle;
    min-width: @badge-dot-size;
    padding: 0;
  }

  &--count {
    min-width: @badge-basic-width;
    white-space: nowrap;
    box-sizing: border-box;
  }

  &--circle {
    border-radius: calc(@badge-basic-height / 2);
  }

  &__ribbon,
  &__ribbon-right,
  &__triangle-right,
  &__ribbon-left,
  &__triangle-left {
    &-outer {
      position: absolute;
      top: 0;
    }
  }

  &__ribbon,
  &__ribbon-right,
  &__triangle-right {
    &-outer {
      right: 0;
    }
  }

  &__ribbon-left,
  &__triangle-left {
    &-outer {
      left: 0;
    }
  }

  &--bubble {
    border-radius: @border-bubble-border-radius;
  }

  &--ribbon,
  &--ribbon-right,
  &--ribbon-left,
  &--triangle-left,
  &--triangle-right {
    width: calc(@badge-basic-height * 2);
    height: calc(@badge-basic-height * 2);
    border-radius: 0;
    padding: 0;
    position: absolute;
    top: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
  }

  &--ribbon,
  &--ribbon-right {
    background: linear-gradient(45deg, transparent 50%, @badge-color 50%, @badge-color 85%, transparent 85%);
  }

  &--triangle-right {
    background: linear-gradient(45deg, transparent 50%, @badge-color 50%);
  }

  &--ribbon,
  &--ribbon-right,
  &--triangle-right {
    right: 0;

    .@{prefix}-badge__count {
      transform: rotate(45deg) translateY(calc(-1 * var(--td-line-height-mark-extraSmall, 32rpx) / 2 + 1rpx));
    }
  }

  &--ribbon-left {
    background: linear-gradient(-45deg, transparent 50%, @badge-color 50%, @badge-color 85%, transparent 85%);
  }

  &--triangle-left {
    background: linear-gradient(-45deg, transparent 50%, @badge-color 50%);
  }

  &--ribbon-left,
  &--triangle-left {
    left: 0;

    .@{prefix}-badge__count {
      transform: rotate(-45deg) translateY(calc(-1 * var(--td-line-height-mark-extraSmall, 32rpx) / 2 + 1rpx));
    }
  }

  // size
  &--large {
    font: @badge-large-font;
    height: @badge-large-height;
    min-width: @badge-large-height;
    padding: 0 @badge-large-padding;
  }

  &--large&--circle {
    border-radius: calc(@badge-large-height / 2);
  }

  &--large&--ribbon,
  &--large&--ribbon-right,
  &--large&--ribbon-left,
  &--large&--triangle-right,
  &--large&--triangle-left {
    width: calc(@badge-large-height * 2);
    height: calc(@badge-large-height * 2);
    padding: 0;
  }

  &--large&--ribbon,
  &--large&--ribbon-right,
  &--large&--triangle-right {
    .@{prefix}-badge__count {
      transform: rotate(45deg) translateY(calc(-1 * var(--td-line-height-mark-small, 40rpx) / 2 + 3rpx));
    }
  }

  &--large&--ribbon-left,
  &--large&--triangle-left {
    .@{prefix}-badge__count {
      transform: rotate(-45deg) translateY(calc(-1 * var(--td-line-height-mark-small, 40rpx) / 2 + 3rpx));
    }
  }

  &__content:not(:empty) + &--bubble.@{prefix}-has-count,
  &__content:not(:empty) + &--circle.@{prefix}-has-count,
  &__content:not(:empty) + &--square.@{prefix}-has-count {
    transform-origin: center center;
    transform: translate(-50%, -50%);
    position: absolute;
    top: 0;
    left: 100%;
  }

  &__content-text {
    display: block;
    font: @badge-content-text-font;
    color: @badge-content-text-color;
  }

  &__count {
    &:empty {
      display: none;
    }
  }
}

@import '../../../common/style/base.less';

@button-border-width: var(--td-button-border-width, 4rpx);
@button-border-radius: var(--td-button-border-radius, @radius-default);

@button-extra-small-font: var(--td-button-extra-small-font, @font-mark-medium);
@button-small-font: var(--td-button-small-font, @font-mark-medium);
@button-medium-font: var(--td-button-medium-font, @font-mark-large);
@button-large-font: var(--td-button-large-font, @font-mark-large);

@button-extra-small-height: var(--td-button-extra-small-height, 56rpx);
@button-small-height: var(--td-button-small-height, 64rpx);
@button-medium-height: var(--td-button-medium-height, 80rpx);
@button-large-height: var(--td-button-large-height, 96rpx);

// button icon
@button-icon-spacer: var(--td-button-icon-spacer, @spacer);
@button-icon-border-radius: var(--td-button-icon-border-radius, 8rpx);

// padding
@button-extra-small-padding-horizontal: var(--td-button-extra-small-padding-horizontal, @spacer);
@button-small-padding-horizontal: var(--td-button-small-padding-horizontal, @spacer-1);
@button-medium-padding-horizontal: var(--td-button-medium-padding-horizontal, @spacer-2);
@button-large-padding-horizontal: var(--td-button-large-padding-horizontal, 40rpx);

// 图标大小
@button-extra-small-icon-size: var(--td-button-extra-small-icon-size, 36rpx);
@button-small-icon-size: var(--td-button-small-icon-size, 36rpx);
@button-medium-icon-size: var(--td-button-medium-icon-size, 40rpx);
@button-large-icon-size: var(--td-button-large-icon-size, 48rpx);

// default
@button-default-color: var(--td-button-default-color, @text-color-primary);
@button-default-bg-color: var(--td-button-default-bg-color, @bg-color-component);
@button-default-border-color: var(--td-button-default-border-color, @bg-color-component);
@button-default-disabled-color: var(--td-button-default-disabled-color, @text-color-disabled);
@button-default-disabled-bg: var(--td-button-default-disabled-bg, @bg-color-component-disabled);
@button-default-disabled-border-color: var(--td-button-default-disabled-border-color, @bg-color-component-disabled);
// primary
@button-primary-color: var(--td-button-primary-color, @text-color-anti);
@button-primary-border-color: var(--td-button-primary-border-color, @brand-color);
@button-primary-bg-color: var(--td-button-primary-bg-color, @brand-color);
@button-primary-disabled-color: var(--td-button-primary-disabled-color, @text-color-anti);
@button-primary-disabled-bg: var(--td-button-primary-disabled-bg, @brand-color-disabled);
@button-primary-disabled-border-color: var(--td-button-primary-disabled-border-color, @brand-color-disabled);
// light
@button-light-color: var(--td-button-light-color, @brand-color);
@button-light-border-color: var(--td-button-light-border-color, @brand-color-light);
@button-light-bg-color: var(--td-button-light-bg-color, @brand-color-light);
@button-light-disabled-color: var(--td-button-light-disabled-color, @brand-color-disabled);
@button-light-disabled-bg: var(--td-button-light-disabled-bg, @brand-color-light);
@button-light-disabled-border-color: var(--td-button-light-disabled-border-color, @brand-color-light);
// danger
@button-danger-color: var(--td-button-danger-color, @text-color-anti);
@button-danger-border-color: var(--td-button-danger-border-color, @error-color);
@button-danger-bg-color: var(--td-button-danger-bg-color, @error-color);
@button-danger-disabled-color: var(--td-button-danger-disabled-color, @font-white-1);
@button-danger-disabled-bg: var(--td-button-danger-disabled-bg, @error-color-3);
@button-danger-disabled-border-color: var(--td-button-danger-disabled-border-color, @error-color-3);
// default + outline
@button-default-outline-color: var(--td-button-default-outline-color, @text-color-primary);
@button-default-outline-border-color: var(--td-button-default-outline-border-color, @component-border);
@button-default-outline-disabled-color: var(--td-button-default-outline-disabled-color, @component-border);
// primary + outline
@button-primary-outline-color: var(--td-button-primary-outline-color, @brand-color);
@button-primary-outline-border-color: var(--td-button-primary-outline-border-color, @button-primary-outline-color);
@button-primary-outline-disabled-color: var(--td-button-primary-outline-disabled-color, @brand-color-disabled);
// danger + outline
@button-danger-outline-color: var(--td-button-danger-outline-color, @error-color);
@button-danger-outline-border-color: var(--td-button-danger-outline-border-color, @button-danger-outline-color);
@button-danger-outline-disabled-color: var(--td-button-danger-outline-disabled-color, @error-color-3);
// light + outline
@button-light-outline-color: var(--td-button-light-outline-color, @brand-color);
@button-light-outline-border-color: var(--td-button-light-outline-border-color, @button-light-outline-color);
@button-light-outline-bg-color: var(--td-button-light-outline-bg-color, @brand-color-light);
@button-light-outline-disabled-color: var(--td-button-light-outline-disabled-color, @brand-color-disabled);
// primary + dashed
@button-primary-dashed-color: var(--td-button-primary-dashed-color, @brand-color);
@button-primary-dashed-border-color: var(--td-button-primary-dashed-border-color, @button-primary-dashed-color);
@button-primary-dashed-disabled-color: var(--td-button-primary-dashed-disabled-color, @brand-color-disabled);
// danger + dashed
@button-danger-dashed-color: var(--td-button-danger-dashed-color, @error-color);
@button-danger-dashed-border-color: var(--td-button-danger-dashed-border-color, @button-danger-dashed-color);
@button-danger-dashed-disabled-color: var(--td-button-danger-dashed-disabled-color, @button-danger-disabled-color);
// primary + text
@button-primary-text-color: var(--td-button-primary-text-color, @brand-color);
@button-primary-text-disabled-color: var(--td-button-primary-text-disabled-color, @brand-color-disabled);
// danger + text
@button-danger-text-color: var(--td-button-danger-text-color, @error-color);
@button-danger-text-disabled-color: var(--td-button-danger-text-disabled-color, @button-danger-disabled-color);
// light + text
@button-light-text-color: var(--td-button-light-text-color, @brand-color);
// ghost 优先级高于 theme，固定透明背景，白色边框，白色字体
@button-ghost-color: var(--td-button-ghost-color, @text-color-anti);
@button-ghost-border-color: var(--td-button-ghost-border-color, @button-ghost-color);
@button-ghost-disabled-color: var(--td-button-ghost-disabled-color, @font-white-4);
@button-ghost-hover-color: var(--td-button-ghost-hover-color, @font-white-2);
@button-ghost-primary-color: var(--td-button-ghost-primary-color, @brand-color);
@button-ghost-primary-border-color: var(--td-button-ghost-primary-border-color, @brand-color);
@button-ghost-primary-hover-color: var(--td-button-ghost-primary-hover-color, @brand-color-active);
@button-ghost-danger-color: var(--td-button-ghost-danger-color, @error-color);
@button-ghost-danger-border-color: var(--td-button-ghost-danger-border-color, @error-color);
@button-ghost-danger-hover-color: var(--td-button-ghost-danger-hover-color, @error-color-active);

// 激活态背景和边框色
@button-default-active-bg-color: var(--td-button-default-active-bg-color, @bg-color-component-active);
@button-default-active-border-color: var(--td-button-default-active-border-color, @bg-color-component-active);
@button-light-active-bg-color: var(--td-button-light-active-bg-color, @brand-color-light-active);
@button-light-active-border-color: var(--td-button-light-active-border-color, @brand-color-light-active);
@button-primary-active-bg-color: var(--td-button-primary-active-bg-color, @brand-color-active);
@button-primary-active-border-color: var(--td-button-primary-active-border-color, @brand-color-active);
@button-danger-active-bg-color: var(--td-button-danger-active-bg-color, @error-color-active);
@button-danger-active-border-color: var(--td-button-danger-active-border-color, @error-color-active);
@button-default-outline-active-bg-color: var(--td-button-default-outline-active-bg-color, @bg-color-container-active);
@button-default-outline-active-border-color: var(--td-button-default-outline-active-border-color, @component-border);
@button-primary-outline-active-bg-color: var(--td-button-primary-outline-active-bg-color, @bg-color-container-active);
@button-primary-outline-active-border-color: var(--td-button-primary-outline-active-border-color, @brand-color-active);
@button-danger-outline-active-bg-color: var(--td-button-danger-outline-active-bg-color, @bg-color-container-active);
@button-danger-outline-active-border-color: var(--td-button-danger-outline-active-border-color, @error-color-active);
@button-light-outline-active-bg-color: var(--td-button-light-outline-active-bg-color, @brand-color-light-active);
@button-light-outline-active-border-color: var(--td-button-light-outline-active-border-color, @brand-color-active);
@button-default-text-active-bg-color: var(--td-button-default-text-active-bg-color, @bg-color-container-active);
@button-primary-text-active-bg-color: var(--td-button-primary-text-active-bg-color, @bg-color-container-active);
@button-danger-text-active-bg-color: var(--td-button-danger-text-active-bg-color, @bg-color-container-active);
@button-light-text-active-bg-color: var(--td-button-light-text-active-bg-color, @bg-color-container-active);

@button: ~'@{prefix}-button';

.button-size(@size) {
  @font: 'button-@{size}-font';
  @padding: 'button-@{size}-padding-horizontal';
  @height: 'button-@{size}-height';
  @iconSize: 'button-@{size}-icon-size';

  .@{button}--size-@{size} {
    font: @@font;
    padding-left: @@padding;
    padding-right: @@padding;
    height: @@height;

    & .@{button}__icon {
      font-size: @@iconSize;
    }
  }
}

.button-theme(@theme) {
  @color: 'button-@{theme}-color';
  @bgColor: 'button-@{theme}-bg-color';
  @borderColor: 'button-@{theme}-border-color';
  @disabledColor: 'button-@{theme}-disabled-color';
  @disabledBorderColor: 'button-@{theme}-disabled-border-color';
  @disabledBgColor: 'button-@{theme}-disabled-bg';
  @activeBgColor: 'button-@{theme}-active-bg-color';
  @activeBorderColor: 'button-@{theme}-active-border-color';

  .@{button}--@{theme} {
    color: @@color;
    background-color: @@bgColor;

    &::after {
      border-width: @button-border-width;
      border-color: @@borderColor;
    }
    border-color: @@borderColor;

    &.@{button}--hover {
      z-index: 0;
      &,
      &::after {
        background-color: @@activeBgColor;
        border-color: @@activeBorderColor;
      }
    }

    &.@{button}--disabled {
      color: @@disabledColor;
      background-color: @@disabledBgColor;

      &,
      &::after {
        border-color: @@disabledBorderColor;
      }
    }
  }
}

.button-size(extra-small);
.button-size(small);
.button-size(medium);
.button-size(large);

.button-theme(default);
.button-theme(primary);
.button-theme(light);
.button-theme(danger);

.ghost-theme(@theme) {
  @color: 'button-ghost-@{theme}-color';
  @hoverColor: 'button-ghost-@{theme}-hover-color';
  @borderColor: 'button-ghost-@{theme}-border-color';

  &.@{button}--@{theme} when (@theme = primary), (@theme = danger) {
    color: @@color;

    &,
    &::after {
      border-color: @@borderColor;
    }

    &.@{button}--hover {
      color: @@hoverColor;

      &,
      &::after {
        background-color: transparent;
        border-color: @@hoverColor;
      }
    }
  }

  &.@{button}--@{theme} {
    &.@{button}--text.@{button}--hover,
    &.@{button}--text.@{button}--hover::after {
      background-color: @gray-color-10;
    }

    &.@{button}--disabled {
      background-color: transparent;
      color: @button-ghost-disabled-color;

      &,
      &::after {
        border-color: @button-ghost-disabled-color;
      }
    }
  }
}

.@{button} {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  white-space: nowrap;
  text-align: center;
  background-image: none;
  transition: all 0.3s;
  touch-action: manipulation;
  border-radius: @button-border-radius;
  outline: none;
  vertical-align: top;
  box-sizing: border-box;

  .cursor-pointer();

  /* stylelint-disable-next-line */
  -webkit-appearance: none;

  &::after {
    border-radius: calc(@button-border-radius * 2);
  }

  &--text {
    color: @button-default-color;
    background-color: transparent;

    &,
    &::after {
      border: 0;
    }

    &.@{button}--hover,
    &.@{button}--hover::after {
      background-color: @button-default-text-active-bg-color;
    }

    &.@{button}--primary {
      color: @button-primary-text-color;
      background-color: transparent;

      &.@{button}--hover,
      &.@{button}--hover::after {
        background-color: @button-primary-text-active-bg-color;
      }

      &.@{button}--disabled {
        color: @button-primary-text-disabled-color;
        background-color: @bg-color-container;
      }
    }

    &.@{button}--danger {
      color: @button-danger-text-color;
      background-color: transparent;

      &.@{button}--hover,
      &.@{button}--hover::after {
        background-color: @button-danger-text-active-bg-color;
      }

      &.@{button}--disabled {
        color: @button-danger-text-disabled-color;
        background-color: @bg-color-container;
      }
    }

    &.@{button}--light {
      color: @button-light-text-color;
      background-color: transparent;

      &.@{button}--hover,
      &.@{button}--hover::after {
        background-color: @button-light-text-active-bg-color;
      }
    }

    &.@{button}--disabled {
      color: @button-default-disabled-color;
    }
  }

  &--outline {
    color: @button-default-outline-color;
    background-color: @bg-color-container;

    &,
    &::after {
      border-color: @button-default-outline-border-color;
    }

    &.@{button}--hover,
    &.@{button}--hover::after {
      background-color: @button-default-outline-active-bg-color;
      border-color: @button-default-outline-active-border-color;
    }

    &.@{button}--disabled {
      color: @button-default-outline-disabled-color;

      &,
      &::after {
        border-color: @button-default-outline-disabled-color;
      }
    }

    &.@{button}--primary {
      color: @button-primary-outline-color;

      &,
      &::after {
        border-color: @button-primary-outline-border-color;
      }

      &.@{button}--hover {
        color: @button-primary-outline-active-border-color;

        &::after {
          background-color: @button-primary-outline-active-bg-color;
          border-color: @button-primary-outline-active-border-color;
        }
      }

      &.@{button}--disabled {
        background-color: transparent;
        color: @button-primary-outline-disabled-color;

        &,
        &::after {
          border-color: @button-primary-outline-disabled-color;
        }
      }
    }

    &.@{button}--danger {
      color: @button-danger-outline-color;

      &,
      &::after {
        border-color: @button-danger-outline-border-color;
      }

      &.@{button}--hover {
        color: @button-danger-outline-active-border-color;

        &::after {
          background-color: @button-danger-outline-active-bg-color;
          border-color: @button-danger-outline-active-border-color;
        }
      }

      &.@{button}--disabled {
        background-color: @bg-color-container;
        color: @button-danger-outline-disabled-color;

        &,
        &::after {
          border-color: @button-danger-outline-disabled-color;
        }
      }
    }

    &.@{button}--light {
      color: @button-light-outline-color;
      background-color: @button-light-outline-bg-color;

      &,
      &::after {
        border-color: @button-light-outline-border-color;
      }

      &.@{button}--hover {
        color: @button-light-outline-active-border-color;

        &,
        &::after {
          background-color: @button-light-outline-active-bg-color;
          border-color: @button-light-outline-active-border-color;
        }
      }

      &.@{button}--disabled {
        background-color: @bg-color-container;
        color: @button-light-outline-disabled-color;

        &,
        &::after {
          border-color: @button-light-outline-disabled-color;
        }
      }
    }
  }

  &--dashed {
    background-color: @bg-color-container;
    border-style: dashed;
    border-width: 2rpx;

    &::after {
      border: 0;
    }

    &.@{button}--hover,
    &.@{button}--hover::after {
      background-color: @button-default-outline-active-bg-color;
      border-color: @button-default-outline-active-border-color;
    }

    &.@{button}--primary {
      color: @button-primary-dashed-color;

      &,
      &::after {
        border-color: @button-primary-dashed-border-color;
      }

      &.@{button}--disabled {
        background-color: @bg-color-container;
        color: @button-primary-dashed-disabled-color;

        &,
        &::after {
          border-color: @button-primary-dashed-disabled-color;
        }
      }
    }

    &.@{button}--danger {
      color: @button-danger-dashed-color;

      &,
      &::after {
        border-color: @button-danger-dashed-border-color;
      }

      &.@{button}--disabled {
        background-color: transparent;
        color: @button-danger-dashed-disabled-color;

        &::after {
          border-color: @button-danger-dashed-disabled-color;
        }
      }
    }
  }

  &--ghost {
    background-color: transparent;
    color: @button-ghost-color;

    &,
    &::after {
      border-color: @button-ghost-border-color;
    }

    &.@{button}--default.@{button}--hover {
      color: @button-ghost-hover-color;

      &,
      &::after {
        background-color: transparent;
        border-color: @button-ghost-hover-color;
      }
    }

    // 不考虑 ghost + light 场景
    .ghost-theme(primary);
    .ghost-theme(danger);
    .ghost-theme(default);
  }

  &__loading + &__content:not(:empty),
  &__icon + &__content:not(:empty) {
    margin-left: calc(@spacer / 2);
  }

  &__icon {
    border-radius: @button-icon-border-radius;
  }

  // 圆角长方形
  &--round {
    &.@{button}--size-large {
      border-radius: calc(@button-large-height / 2);

      &::after {
        border-radius: @button-large-height;
      }
    }

    &.@{button}--size-medium {
      border-radius: calc(@button-medium-height / 2);

      &::after {
        border-radius: @button-medium-height;
      }
    }

    &.@{button}--size-small {
      border-radius: calc(@button-small-height / 2);

      &::after {
        border-radius: @button-small-height;
      }
    }

    &.@{button}--size-extra-small {
      border-radius: calc(@button-extra-small-height / 2);

      &::after {
        border-radius: @button-extra-small-height;
      }
    }
  }

  // 正方形
  &--square {
    padding: 0;

    &.@{button}--size-large {
      width: @button-large-height;
    }

    &.@{button}--size-medium {
      width: @button-medium-height;
    }

    &.@{button}--size-small {
      width: @button-small-height;
    }

    &.@{button}--size-extra-small {
      width: @button-extra-small-height;
    }
  }

  // 圆形
  &--circle {
    padding: 0;
    border-radius: @radius-circle;

    &.@{button}--size-large {
      width: @button-large-height;

      &::after {
        border-radius: @radius-circle;
      }
    }

    &.@{button}--size-medium {
      width: @button-medium-height;

      &::after {
        border-radius: @radius-circle;
      }
    }

    &.@{button}--size-small {
      width: @button-small-height;

      &::after {
        border-radius: @radius-circle;
      }
    }

    &.@{button}--size-extra-small {
      width: @button-extra-small-height;

      &::after {
        border-radius: @radius-circle;
      }
    }
  }

  &--block {
    display: flex;
    width: 100%;
  }

  &--disabled {
    cursor: not-allowed;
  }

  &__loading {
    &--wrapper {
      display: flex;
      align-items: center;
      justify-content: center;
    }
  }

  &.@{button}--hover::after {
    z-index: -1;
  }
}

// @import (css) '../../../common/index.wxss';
@import '../../../common/style/base.less';

@cell-group-title-font-size: var(--td-cell-group-title-font-size, @font-size-base);
@cell-group-title-line-height: var(--td-cell-group-title-line-height, 90rpx);
@cell-group-title-padding-left: var(--td-cell-group-title-padding-left, @spacer-2);
@cell-group-title-bg-color: var(--td-cell-group-title-bg-color, @bg-color-secondarycontainer);
@cell-group-title-color: var(--td-cell-group-title-color, @text-color-placeholder);
@cell-group-border-color: var(--td-cell-group-border-color, @component-stroke);

.@{prefix}-cell-group {
  position: relative;

  &__title {
    font-family: PingFangSC-Regular;
    font-size: @cell-group-title-font-size;
    color: @cell-group-title-color;
    text-align: left;
    line-height: @cell-group-title-line-height;
    background-color: @cell-group-title-bg-color;
    padding-left: @cell-group-title-padding-left;
  }

  &--bordered {
    &::before {
      .hairline-top(@cell-group-border-color);
      transform-origin: top;
      z-index: 1;
    }

    &::after {
      .hairline-bottom(@cell-group-border-color);
      transform-origin: bottom;
      z-index: 1;
    }
  }

  &--card {
    margin: 0 @spacer-2;
    border-radius: @radius-large;
    overflow: hidden;
  }
}

@import '../../../common/style/base.less';

@checkbox: ~'@{prefix}-checkbox';

@checkbox-border-width: 4rpx;
@checkbox-icon-size: var(--td-checkbox-icon-size, 48rpx);
@checkbox-title-font: var(--td-checkbox-title-font, @font-body-large);
@checkbox-title-line-height: var(--td-checkbox-title-line-height, @text-line-height-m);
@checkbox-description-font: var(--td-checkbox-description-font, @font-body-medium);
@checkbox-vertical-padding: var(--td-checkbox-vertical-padding, @spacer-2);
@checkbox-bg-color: var(--td-checkbox-bg-color, @bg-color-container);
@checkbox-border-color: var(--td-checkbox-border-color, @component-stroke);
@checkbox-title-color: var(--td-checkbox-title-color, @text-color-primary);
@checkbox-title-disabled-color: var(--td-checkbox-title-disabled-color, @text-color-disabled);
@checkbox-description-color: var(--td-checkbox-description-color, @text-color-secondary);
@checkbox-description-disabled-color: var(--td-checkbox-description-disabled-color, @text-color-disabled);
@checkbox-icon-color: var(--td-checkbox-icon-color, @component-border);
@checkbox-icon-disabled-color: var(--td-checkbox-icon-disabled-color, @brand-color-disabled);
@checkbox-icon-disabled-bg-color: var(--td-checkbox-icon-disabled-bg-color, @bg-color-component-disabled);
@checkbox-icon-checked-color: var(--td-checkbox-icon-checked-color, @brand-color);
@checkbox-tag-active-bg-color: var(--td-checkbox-tag-active-bg-color, @brand-color-light);
@checkbox-tag-active-color: var(--td-checkbox-tag-active-color, @brand-color);

.@{checkbox} {
  display: inline-flex;
  vertical-align: middle;
  position: relative;
  background: @checkbox-bg-color;

  &:focus {
    outline: 0;
  }

  &--block {
    display: flex;
    padding: @checkbox-vertical-padding;
  }

  &--horizontal {
    padding: 0;
    margin-right: @spacer-2;
  }

  &--right {
    flex-direction: row-reverse;
  }

  .limit-title-row {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .image-center {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
  }

  &__icon-left {
    margin-right: 20rpx;
    width: 40rpx;
  }

  &__icon-right {
    right: 0px;
    display: contents;
    .image-center();
  }

  &__icon-image {
    width: @checkbox-icon-size;
    height: @checkbox-icon-size;
    vertical-align: top;
  }

  &__icon {
    position: relative;
    display: block;
    width: @checkbox-icon-size;
    height: @checkbox-icon-size;
    color: @checkbox-icon-color;
    font-size: @checkbox-icon-size;
    margin-top: calc((@checkbox-title-line-height - @checkbox-icon-size) / 2);

    &:empty {
      display: none;
    }

    &--checked {
      color: @checkbox-icon-checked-color;
    }

    &--disabled {
      cursor: not-allowed;
      color: @checkbox-icon-disabled-color;
    }

    &--left {
      margin-right: @spacer;
    }

    &-circle {
      width: calc((@checkbox-icon-size - @checkbox-border-width) * 2);
      height: calc((@checkbox-icon-size - @checkbox-border-width) * 2);
      border: calc(@checkbox-border-width * 2) solid @checkbox-icon-color;
      border-radius: @radius-circle;
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%) scale(0.5);
      box-sizing: border-box;

      &--disabled {
        background: @checkbox-icon-disabled-bg-color;
      }
    }

    &-rectangle {
      width: calc((@checkbox-icon-size - @checkbox-border-width * 2) * 2);
      height: calc((@checkbox-icon-size - @checkbox-border-width * 2) * 2);
      border: calc(@checkbox-border-width * 2) solid @checkbox-icon-color;
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%) scale(0.5);
      box-sizing: border-box;

      &--disabled {
        background: @checkbox-icon-disabled-bg-color;
      }
    }

    &-line {
      &::before,
      &::after {
        content: '';
        display: block;
        position: absolute;
        width: 5rpx;
        border-radius: 2rpx;
        background: @checkbox-icon-checked-color;
        transform-origin: top center;
      }

      &::before {
        height: 16rpx;
        left: 8rpx;
        top: 22rpx;
        transform: rotate(-45deg);
      }

      &::after {
        height: 26rpx;
        right: 8rpx;
        top: 14rpx;
        transform: rotate(45deg);
      }

      &--disabled {
        &::before,
        &::after {
          background: @checkbox-icon-disabled-color;
        }
      }
    }
  }

  &__content {
    flex: 1;
  }

  &__title {
    color: @checkbox-title-color;
    font: @checkbox-title-font;
    line-height: @checkbox-title-line-height;

    .limit-title-row();

    &--disabled {
      color: @checkbox-title-disabled-color;
    }
  }

  &__description {
    color: @checkbox-description-color;
    .limit-title-row();

    font: @checkbox-description-font;

    &--disabled {
      color: @checkbox-description-disabled-color;
    }
  }

  &__title + &__description:not(:empty) {
    margin-top: calc(@spacer / 2);
  }

  &__border {
    position: absolute;
    bottom: 0;
    left: 96rpx;
    right: 0;
    height: 1px;
    background: @checkbox-border-color;
    transform: scaleY(0.5);

    &--right {
      left: 32rpx;
    }
  }

  // theme = tag 启用
  &--tag {
    font-size: @font-size-base;
    padding-top: @spacer;
    padding-bottom: @spacer;
    text-align: center;
    background-color: @bg-color-secondarycontainer;
    border-radius: @radius-default;

    &.@{checkbox}--checked {
      color: @checkbox-tag-active-color;
      background-color: @checkbox-tag-active-bg-color;
    }

    .@{checkbox}__title--checked {
      color: @checkbox-tag-active-color;
    }

    .@{checkbox}__content {
      margin-right: 0;
    }
  }
}

