@countdown-square-border-radius: var(--td-countdown-square-border-radius, @radius-small);
// 带圆形底倒计时圆角大小
@countdown-round-border-radius: var(--td-countdown-round-border-radius, @radius-circle);

@countdown-number-font-family:
  TCloudNumber,
  -apple-system,
  BlinkMacSystemFont,
  Segoe UI,
  Roboto,
  Hiragino Sans GB,
  Microsoft YaHei UI,
  Microsoft YaHei,
  Source Han Sans CN,
  sans-serif,
  Apple Color Emoji,
  Segoe UI Emoji,
  Segoe UI Symbol;

@countdown: ~'@{prefix}-count-down';
@item: ~'@{countdown}__item';
@split: ~'@{countdown}__split';

.count-down-size(@size) {
  .@{countdown} {
    @defaultFontSize: 'countdown-@{size}-default-font-size';
    @roundFontSize: 'countdown-@{size}-round-font-size';
    @squareFontSize: 'countdown-@{size}-square-font-size';
    @width: 'countdown-@{size}-bg-width';
    @height: 'countdown-@{size}-bg-width';
    @dotMargin: 'countdown-@{size}-no-unit-margin';
    @dotFontSize: 'countdown-@{size}-no-unit-font-size';
    @textMargin: 'countdown-@{size}-unit-margin';
    @textFontSize: 'countdown-@{size}-unit-font-size';

    &--@{size} {
      &.@{countdown}--default {
        font-size: @@defaultFontSize;
      }

      &.@{countdown}--round {
        > .@{item} {
          font-size: @@roundFontSize;
        }
      }

      &.@{countdown}--square {
        > .@{item} {
          font-size: @@squareFontSize;
        }
      }

      &.@{countdown}--round,
      &.@{countdown}--square {
        > .@{item} {
          width: @@width;
          height: @@height;
        }
      }

      &.@{countdown}--round,
      &.@{countdown}--square {
        > .@{split}--dot {
          margin: 0 @@dotMargin;
          font-size: @@dotFontSize;
          font-weight: 700;
        }

        > .@{split}--text {
          margin: 0 @@textMargin;
          font-size: @@textFontSize;
        }
      }
    }
  }
}

.count-down-size(small);
.count-down-size(medium);
.count-down-size(large);

.@{countdown} {
  font-family: @countdown-number-font-family;
  display: flex;

  .@{item},
  .@{split} {
    display: flex;
    align-items: center;
    justify-content: center;
  }

  &--square,
  &--round {
    > .@{split}--dot {
      color: @countdown-no-unit-color;
    }

    > .@{split}--text {
      color: @countdown-unit-color;
    }
  }

  &--default {
    color: @countdown-default-text-color;
  }

  &--square {
    color: @countdown-text-color;

    > .@{item} {
      border-radius: @countdown-square-border-radius;
      background: @countdown-bg-color;
    }
  }

  &--round {
    color: @countdown-text-color;

    > .@{item} {
      border-radius: @countdown-round-border-radius;
      background: @countdown-bg-color;
    }
  }
}

@import '../../../common/style/base.less';

@drawer-width: var(--td-drawer-width, 560rpx);
@drawer-title-font: var(--td-drawer-title-font, @font-title-large);
@drawer-title-padding: var(--td-drawer-title-padding, @spacer-3 @spacer-2 @spacer);
@drawer-bg-color: var(--td-drawer-bg-color, @bg-color-container);
@drawer-border-color: var(--td-drawer-border-color, @border-level-1-color);
@drawer-title-color: var(--td-drawer-title-color, @text-color-primary);
@drawer-item-icon-color: var(--td-drawer-item-icon-color, @drawer-title-color);
@drawer-item-padding: var(--td-drawer-item-padding, @spacer-2);
@drawer-item-icon-size: var(--td-drawer-item-icon-size, 48rpx);
@drawer-sidebar-height: var(--td-drawer-sidebar-height, 70vh);
@drawer-footer-padding-bottom: var(--td-drawer-footer-padding-bottom, 40rpx);
@drawer-hover-color: var(--td-drawer-hover-color, @bg-color-secondarycontainer);

.@{prefix}-drawer {
  background: @drawer-bg-color;
  width: @drawer-width;
  height: 100%;
  display: flex;
  flex-direction: column;

  &--hover {
    background-color: @drawer-hover-color;
  }

  &__title {
