@import '../../../common/style/base.less';

@dropdown-menu-bg-color: var(--td-dropdown-menu-bg-color, @bg-color-container);
@dropdown-body-max-height: var(--td-dropdown-body-max-height, 560rpx);

@item: ~'@{prefix}-dropdown-item';

/** dropdown-item */
.@{item} {
  position: fixed;
  right: 0;
  left: 0;
  top: 0;
  overflow: hidden;
  bottom: 0;
  z-index: @z-index-dropdown-menu;

  &__content {
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  &__popup-host {
    // 为了解决虚拟节点偶尔出现的问题
    display: block;
    width: 100%;
    overflow: hidden;
    position: absolute;
    left: 0;
    top: 0;
  }

  &__body {
    flex: 1;
    background: @dropdown-menu-bg-color;
    overflow: auto;
    max-height: @dropdown-body-max-height;

    &--tree {
      display: flex;
      overflow: hidden;
    }

    &--multi {
      padding-top: @spacer;
      padding-bottom: @spacer;
      overflow-y: auto;
    }
  }

  &__scroll {
    max-height: @dropdown-body-max-height;
  }

  &__footer {
    display: flex;
    background: @dropdown-menu-bg-color;
    position: relative;
    padding: @spacer-2;
    .border(top, @component-border);

    &-btn {
      flex: 1;
    }

    &-btn + &-btn {
      margin-left: @spacer-2;
    }
  }

  &__body,
  &__footer {
    &:empty {
      display: none;
    }
  }

  &__radio,
  &__checkbox {
    width: 100%;
    overflow: scroll;
    box-sizing: border-box;

    &-group {
      display: grid;
      grid-gap: @spacer-1;
    }
  }

  &__radio {
    &-group {
      display: grid;
      grid-gap: 0;
    }
  }

  &__checkbox {
    &-group {
      padding: @spacer-2;
    }
  }

  &__mask {
    position: fixed;
    width: 100vh;
    top: 0;
    left: 0;
  }
}

@import '../../../common/style/base.less';

@dropdown-menu-height: var(--td-dropdown-menu-height, 96rpx);
@dropdown-menu-bg-color: var(--td-dropdown-menu-bg-color, @bg-color-container);
@dropdown-menu-color: var(--td-dropdown-menu-color, @text-color-primary);
@dropdown-menu-active-color: var(--td-dropdown-menu-active-color, @brand-color);
@dropdown-menu-disabled-color: var(--td-dropdown-menu-disabled-color, @text-color-disabled);
@dropdown-menu-font-size: var(--td-dropdown-menu-font-size, @font-size-base);
@dropdown-menu-icon-size: var(--td-dropdown-menu-icon-size, 40rpx);
@dropdown-menu-border-width: var(--td-dropdown-menu-border-width, 1px);

@dropdownMenu: ~'@{prefix}-dropdown-menu';

.@{dropdownMenu} {
  position: relative;
  display: flex;
  height: @dropdown-menu-height;
  background: @dropdown-menu-bg-color;
  .border(bottom);

  &:after {
    height: @dropdown-menu-border-width;
  }

  &__item {
    display: flex;
    flex: 1;
    align-items: center;
    justify-content: center;
    padding: 0 @spacer;
    position: relative;
    overflow: hidden;
    color: @dropdown-menu-color;

    &--active {
      color: @dropdown-menu-active-color;
    }

    &--disabled {
      color: @dropdown-menu-disabled-color;
    }
  }

  &__icon {
    font-size: @dropdown-menu-icon-size;
    padding: calc(@spacer / 4);
    box-sizing: border-box;
    transition: transform 240ms ease;

    &--active {
      transform: rotate(180deg);
    }

    &:not(:empty) {
      margin-left: calc(@spacer / 2);
    }
  }

  &__title {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: @dropdown-menu-font-size;
  }
}

@import '../../../common/style/base.less';

@loading: ~'@{prefix}-loading';

@loading-color: var(--td-loading-color, @brand-color);
@loading-text-color: var(--td-loading-text-color, @text-color-primary);
@loading-text-font: var(--td-loading-text-font, @font-body-small);
@loading-z-index: var(--td-loading-z-index, @z-index-loading);
@loading-full-bg-color: var(--td-loading-full-bg-color, rgba(255, 255, 255, 0.6));

.@{loading} {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  &--fullscreen {
    position: fixed;
    display: flex;
    align-items: center;
    vertical-align: middle;
    justify-content: center;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: @loading-z-index;
    background-color: @loading-full-bg-color;
  }

  &__spinner {
    position: relative;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    max-width: 100%;
    max-height: 100%;
    animation: rotate 0.8s linear infinite;
    color: @loading-color;

    &.reverse {
      animation-name: rotateReverse;
    }

    &--spinner {
      animation-timing-function: steps(12);
      color: @text-color-primary;

      .@{loading}__dot {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;

        &::before {
          display: block;
          width: 5rpx;
          height: 25%;
          margin: 0 auto;
          background-color: @loading-color;
          border-radius: 40%;
          content: ' ';
        }
      }
    }

    &--circular {
      .@{loading}__circular {
        border-radius: 100%;
        width: 100%;
        height: 100%;
        background: conic-gradient(
          from 180deg at 50% 50%,
          rgba(255, 255, 255, 0) 0deg,
          rgba(255, 255, 255, 0) 60deg,
          currentColor 330deg,
          rgba(255, 255, 255, 0) 360deg
        );
        mask: radial-gradient(transparent calc(50% - 1rpx), #fff 50%);

        /* stylelint-disable-next-line */
        -webkit-mask: radial-gradient(transparent calc(50% - 1rpx), #fff 50%);
      }
    }

    &--dots {
      display: flex;
      justify-content: space-between;
      align-items: center;
      animation: none;

      .@{loading}__dot {
        width: 20%;
        height: 20%;
        border-radius: @radius-circle;
        background-color: @loading-color;
        animation-duration: 1.8s;
        animation-name: dotting;
        animation-timing-function: linear;
        animation-iteration-count: infinite;
        animation-fill-mode: both;
      }
    }
  }

  &__text {
    color: @loading-text-color;
    font: @loading-text-font;

    &--vertical:not(:first-child):not(:empty) {
      margin-top: 12rpx;
    }

    &--horizontal:not(:first-child):not(:empty) {
      margin-left: @spacer;
    }
  }

  &--vertical {
    flex-direction: column;
  }

  &--horizontal {
    flex-direction: row;
    vertical-align: top;
  }
}

@keyframes t-bar {
  0% {
    width: 0;
  }

  50% {
    width: 70%;
  }

  100% {
    width: 80%;
  }
}

@keyframes t-bar-loaded {
  0% {
    height: 6rpx;
    opacity: 1;
    width: 90%;
  }

  50% {
    height: 6rpx;
    opacity: 1;
    width: 100%;
  }

  100% {
    height: 0;
    opacity: 0;
    width: 100%;
  }
}

.generate(@n, @i: 1) when (@i =< @n) {
  .@{loading}__dot-@{i} {
    transform: rotate(@i * 30deg);
    opacity: (1 / 12) * (@i - 1);
  }
  .generate(@n, (@i + 1));
}
.generate(12);

@keyframes rotate {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

@keyframes rotateReverse {
  from {
    transform: rotate(360deg);
  }

  to {
    transform: rotate(0deg);
  }
}

@keyframes dotting {
  0% {
    opacity: 0.15;
  }

  1% {
    opacity: 0.8;
  }

  33% {
    opacity: 0.8;
  }

  34% {
    opacity: 0.15;
  }

  100% {
    opacity: 0.15;
  }
}

@import '../../../common/style/base.less';

@message-height: 96rpx;
@message-horizontal-padding: @spacer-2;
@message-z-index: @z-index-message;

@message-align: flex-start;
@message-icon-size: 44rpx;
@message-content-font: @font-body-medium;

@message-bg-color: var(--td-message-bg-color, @bg-color-container); // 消息通知背景颜色
@message-box-shadow: var(--td-message-box-shadow, @shadow-1); // 消息通知阴影
@message-border-radius: var(--td-message-border-radius, @radius-default); // 消息通知圆角大小
@message-content-color: var(--td-message-content-color, @text-color-primary); // 内容文本颜色
@message-info-color: var(--td-message-info-color, @brand-color); // 'info'主题色
@message-success-color: var(--td-message-success-color, @success-color); // 'success'主题色
@message-warning-color: var(--td-message-warning-color, @warning-color); // 'warning'主题色
@message-error-color: var(--td-message-error-color, @error-color); // 'error'主题色
@message-close-icon-color: var(--td-message-close-icon-color, @text-color-placeholder); // 关闭按钮图标颜色

@message: ~'@{prefix}-message';

.@{message} {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  transition:
    opacity 0.3s,
    transform 0.4s,
    top 0.4s;
  display: flex;
  justify-content: @message-align;
  height: @message-height;
  align-items: center;
  z-index: @message-z-index;
  padding: 0 @message-horizontal-padding;
  box-sizing: border-box;
  border-radius: @message-border-radius;
  line-height: 1;
  background-color: @message-bg-color;
  box-shadow: @message-box-shadow;

  &__text {
    display: inline-block;
    color: @message-content-color;
    font: @message-content-font;
  }

  &__text-wrap {
    flex: 1 1 auto;
    overflow-x: hidden;
    text-overflow: ellipsis;
  }

  &__text-nowrap {
    word-break: keep-all;
    white-space: nowrap;
  }

  &--info {
    color: @message-info-color;
  }

  &--success {
    color: @message-success-color;
  }

  &--warning {
    color: @message-warning-color;
  }

  &--error {
    color: @message-error-color;
  }

  &__icon--left,
  &__icon--right {
    font-size: @message-icon-size;
  }

  &__icon--left:not(:empty) {
    margin-right: @spacer;
  }

  &__icon--right {
    color: @message-close-icon-color;
  }

  &__icon--right:not(:empty),
  &__link {
    flex: 0 0 auto;
    margin-left: @spacer;
  }
  &__fade {
    opacity: 0;
    transform: translateY(-100%);
  }
}

@import '../../../common/style/base.less';

@search-bg-color: var(--td-search-bg-color, @bg-color-secondarycontainer);
@search-text-color: var(--td-search-text-color, @text-color-primary);
@search-label-color: var(--td-search-label-color, @text-color-primary);
@search-font: var(--td-search-font, @font-body-large);
@search-height: var(--td-search-height, 80rpx);
@search-padding: var(--td-search-padding, @spacer @spacer-1);
@search-placeholder-color: var(--td-search-placeholder-color, @text-color-placeholder);
@search-icon-color: var(--td-search-icon-color, @text-color-placeholder);
@search-disabled-text-color: var(--td-search-disabled-text-color, @text-color-disabled); // 输入框禁用态文本颜色
@search-icon-size: var(--td-search-icon-size, 48rpx);
@search-square-radius: var(--td-search-square-radius, @radius-default);
