.@{prefix}-side-bar-item {
  display: flex;
  align-items: center;
  position: relative;
  padding: @spacer-2;
  font: @side-bar-font;
  color: @side-bar-color;
  background: @side-bar-bg-color;
  min-height: @side-bar-item-height;
  box-sizing: border-box;
  white-space: wrap;

  &--active {
    font-weight: 600;
    background: @bg-color-container;
