@step-item-default-title-color: var(--td-step-item-default-title-color, @text-color-placeholder);
@step-item-default-icon-color: var(--td-step-item-default-icon-color, @text-color-placeholder);
@step-item-default-dot-border-color: var(--td-step-item-default-dot-border-color, @component-border);

@step-item-process-circle-color: var(--td-step-item-process-circle-color, @text-color-anti);
@step-item-process-circle-bg: var(--td-step-item-process-circle-bg, @brand-color);
@step-item-process-title-color: var(--td-step-item-process-title-color, @brand-color);
@step-item-process-icon-color: var(--td-step-item-process-icon-color, @brand-color);
@step-item-process-dot-border-color: var(--td-step-item-process-dot-border-color, @brand-color);

@step-item-finish-circle-color: var(--td-step-item-finish-circle-color, @brand-color);
@step-item-finish-circle-bg: var(--td-step-item-finish-circle-bg, @brand-color-light);
@step-item-finish-title-color: var(--td-step-item-finish-title-color, @text-color-primary);
@step-item-finish-icon-color: var(--td-step-item-finish-icon-color, @brand-color);
@step-item-finish-dot-border-color: var(--td-step-item-finish-dot-border-color, @brand-color);

@step-item-error-circle-color: var(--td-step-item-error-circle-color, @error-color);
@step-item-error-circle-bg: var(--td-step-item-error-circle-bg, @error-color-1);
@step-item-error-title-color: var(--td-step-item-error-title-color, @error-color);
@step-item-error-icon-color: var(--td-step-item-error-icon-color, @error-color);
@step-item-error-dot-border-color: var(--td-step-item-error-dot-border-color, @error-color);

@step-item-line-color: var(--td-step-item-line-color, @component-border);
@step-item-finish-line-color: var(--td-step-item-finish-line-color, @brand-color);

@step: ~'@{prefix}-step';
@steps: ~'@{step}s';
@item: ~'@{steps}-item';

.color-generate() {
  @status: default, process, finish, error;
  each(@status, {
    @bgVar: ~"step-item-@{value}-circle-bg";
    @colorVar: ~"step-item-@{value}-circle-color";
    @titleColorVar: ~"step-item-@{value}-title-color";
    @iconColorVar: ~"step-item-@{value}-icon-color";
    @dotBorderColorVar: ~"step-item-@{value}-dot-border-color";

    &__circle--@{value} {
      color: @@colorVar;
      background-color: @@bgVar;
    }

    &__title--@{value} {
      color: @@titleColorVar;
    }

    &__icon--@{value} {
      color: @@iconColorVar;
    }

    &__dot--@{value} {
      border-color: @@dotBorderColorVar;
      background-color: @@dotBorderColorVar;
    }
  });
}

.@{item} {
  flex: 1;
  vertical-align: top;
  position: relative;
  display: flex;

  .color-generate();

  &--horizontal {
    flex-direction: column;
    justify-content: center;
    align-items: center;
  }

  &--vertical {
    margin-bottom: @spacer;
  }

  &__anchor {
    display: flex;
    align-items: center;
    justify-content: center;

    &--vertical {
      width: @step-item-circle-size;
      height: @step-item-circle-size;
    }
  }

  &__circle {
    display: flex;
    justify-content: center;
    align-items: center;
    width: @step-item-circle-size;
    height: @step-item-circle-size;
    text-align: center;
    border-radius: @radius-circle;
    font: @step-item-circle-text-font;
  }

  &__icon {
    z-index: 1;
    vertical-align: top;
    font-size: @font-size-base;
    position: relative;
  }

  &__dot {
    width: @step-item-dot-size;
    height: @step-item-dot-size;
    border-radius: @radius-circle;
    border-width: 1px;
    border-style: solid;
    box-sizing: border-box;
  }

  &__content {
    text-align: center;

    &--horizontal {
      max-width: 80px;
      margin-top: @spacer;
    }

    &--vertical {
      margin-left: @spacer;
      flex: 1;
      padding-bottom: @spacer-2;
    }

    &--vertical&--last {
      padding-bottom: 0;
    }
  }

  &__title {
    position: relative;
    font: @font-body-medium;

    &--process {
      font-weight: 600;
    }

    &--vertical {
      text-align: left;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
  }

  &__title + &__description:not(:empty) {
    margin-top: calc(@spacer / 2);
  }

  &__description {
    color: @step-item-description-color;
    font: @font-body-small;

    &--vertical {
      text-align: left;
    }
  }

  &__extra {
    &:not(:empty) {
      margin-top: @spacer;
    }
  }

  &__line {
    background-color: @step-item-line-color;
    content: '';
    display: block;
    position: absolute;

    &--horizontal {
      height: 1px;
      transform: translateY(-50%);
      width: calc(100% - 32rpx - @step-item-circle-size);
      top: calc(@step-item-circle-size / 2 + 1px);
      left: calc(50% + @step-item-circle-size / 2 + 16rpx);
    }

    &--horizontal&--dot {
      top: calc(@step-item-dot-size / 2);
    }

    &--finish,
    &--reverse&--process {
      background-color: @step-item-finish-line-color;
    }

    &--vertical {
      height: calc(100% - 32rpx - @step-item-circle-size);
      width: 1px;
      transform: translateX(-50%);
      left: calc(@step-item-circle-size / 2);
      top: calc(@step-item-circle-size + 16rpx);
    }

    &--vertical&--dot {
      top: @step-item-circle-size;
      height: calc(100% - @step-item-circle-size);
    }
  }
}

:host {
  flex: 1;
  vertical-align: top;
  position: relative;
  align-self: flex-start;
  width: inherit;
}

@import '../../../common/style/base.less';

// dot & dots-bar
@swiper-nav-dot-color: var(--td-swiper-nav-dot-color, @font-white-2);
@swiper-nav-dot-active-color: var(--td-swiper-nav-dot-active-color, @text-color-anti);
@swiper-nav-dot-size: var(--td-swiper-nav-dot-size, 12rpx);
@swiper-nav-dots-bar-active-width: var(--td-swiper-nav-dots-bar-active-width, 40rpx);

// fraction
@swiper-nav-fraction-color: var(--td-swiper-nav-fraction-color, @text-color-anti);
@swiper-nav-fraction-bg-color: var(--td-swiper-nav-fraction-bg-color, @font-gray-3);
@swiper-nav-fraction-height: var(--td-swiper-nav-fraction-height, 48rpx);
@swiper-nav-fraction-font: var(--td-swiper-nav-fraction-font, @font-body-small);

// button
@swiper-nav-btn-color: var(--td-swiper-nav-btn-color, @text-color-anti);
@swiper-nav-btn-bg-color: var(--td-swiper-nav-btn-bg-color, @font-gray-3);
@swiper-nav-btn-size: var(--td-swiper-nav-btn-size, 48rpx);

.@{prefix}-swiper-nav {
  &__dots,
  &__dots-bar {
    display: flex;
    flex-direction: row;

    &-item {
      width: @swiper-nav-dot-size;
      height: @swiper-nav-dot-size;
      background: @swiper-nav-dot-color;
      border-radius: @radius-circle;
      margin: 0 10rpx;
      transition: all 0.4s ease-in;

      &--vertical {
        margin: 10rpx 0;
      }

      &--active {
        background-color: @swiper-nav-dot-active-color;
      }
    }
  }

  &__dots-bar {
    &-item {
      &--vertical&--active {
        width: @swiper-nav-dot-size;
        height: @swiper-nav-dots-bar-active-width;
      }
      &--active {
        width: @swiper-nav-dots-bar-active-width;
        border-radius: calc(@swiper-nav-dot-size / 2);
        background-color: @swiper-nav-dot-active-color;
      }
    }
  }

  &--left {
    position: absolute;
    left: 24rpx;
    top: 50%;
    transform: translateY(-50%);
  }

  &--right {
    position: absolute;
    right: 24rpx;
    top: 50%;
    transform: translateY(-50%);
  }

  &--top-left {
    position: absolute;
    top: 24rpx;
    left: 24rpx;
  }

  &--top {
    position: absolute;
    left: 50%;
    top: 24rpx;
    transform: translateX(-50%);
  }

  &--top-right {
    position: absolute;
    top: 24rpx;
    right: 24rpx;
  }

  &--bottom-left {
    position: absolute;
    left: 24rpx;
    bottom: 24rpx;
  }

  &--bottom {
    position: absolute;
    left: 50%;
    bottom: 24rpx;
    transform: translateX(-50%);
  }

  &--bottom-right {
    position: absolute;
    right: 24rpx;
    bottom: 24rpx;
  }

  &--vertical {
    flex-direction: column;
  }

  &__fraction {
    padding: 0 @spacer;
    height: @swiper-nav-fraction-height;
    border-radius: calc(@swiper-nav-fraction-height / 2);
    background: @swiper-nav-fraction-bg-color;
    color: @swiper-nav-fraction-color;
    font: @swiper-nav-fraction-font;
  }

  &__btn {
    width: 100%;
    position: absolute;
    top: 50%;
    transform: translateY(-50%);

    &--prev,
    &--next {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: @swiper-nav-btn-size;
      height: @swiper-nav-btn-size;
      border-radius: @radius-circle;
      background: @swiper-nav-btn-bg-color;

      &::after {
        position: absolute;
        left: 50%;
        top: 50%;
        display: block;
        content: '';
        width: 12rpx;
        height: 12rpx;
        border-color: @swiper-nav-btn-color;
        border-style: solid;
      }
    }

    &--prev {
      left: 30rpx;

      &::after {
        margin-left: calc(@spacer / 4);
        border-width: 2rpx 0 0 2rpx;
        transform: translate(-50%, -50%) rotateZ(-45deg);
      }
    }

    &--next {
      right: 30rpx;

      &::after {
        margin-left: calc(-1 * @spacer / 4);
        border-width: 2rpx 2rpx 0 0;
        transform: translate(-50%, -50%) rotateZ(45deg);
      }
    }
  }
}

@import '../../../common/style/base.less';

@table-prefix: ~'@{prefix}-table';

// 变量
@table-border-color: var(--td-table-border-color, @component-border);
@table-header-bg-color: var(--td-table-header-bg-color, @bg-color-container);
@table-header-text-color: var(--td-table-header-text-color, @text-color-placeholder);
@table-body-text-color: var(--td-table-body-text-color, @text-color-primary);
@table-stripe-bg-color: var(--td-table-stripe-bg-color, @bg-color-secondarycontainer);
@table-td-padding: var(--td-table-td-padding, @spacer @spacer-1);
@table-th-padding: var(--td-table-th-padding, @spacer @spacer-1);
@table-font-size: var(--td-table-font-size, @font-body-medium);
@table-loading-bg-color: var(--td-table-loading-bg-color, rgba(255, 255, 255, 0.55));
@table-row-height: var(--td-table-row-height, 82rpx);
@scrollbar-color: rgba(0, 0, 0, 10%);
@scrollbar-hover-color: rgba(0, 0, 0, 30%);

// 固定列相关变量
@table-fixed-column-z-index: 30;
@table-fixed-cell-border-color: var(--td-table-fixed-cell-border-color, @component-border);
@table-fixed-cell-border-width: 8rpx;
@table-fixed-cell-border-width-light: 4rpx;
@table-fixed-cell-border: @table-fixed-cell-border-width solid @table-fixed-cell-border-color;
@table-fixed-cell-border-light: @table-fixed-cell-border-width-light solid @table-fixed-cell-border-color;

.@{table-prefix} {
  position: relative;
  width: 100%;
  font: @table-font-size;
  color: @table-body-text-color;
  background-color: @bg-color-container;
  box-sizing: border-box;

  &__content {
    position: relative;
    overflow: auto;

    // scrollbar 样式（同步 mobile-vue）
    // scroll-view 在 H5 端内部会生成子滚动容器，需要同时匹配自身和后代元素
    &::-webkit-scrollbar,
    & ::-webkit-scrollbar {
      width: 12rpx;
      height: 12rpx;
    }

    &::-webkit-scrollbar-thumb,
    & ::-webkit-scrollbar-thumb {
      background-clip: content-box;
      background-color: @scrollbar-color;
      border-radius: 22rpx;
    }

    &::-webkit-scrollbar-thumb:vertical:hover,
    &::-webkit-scrollbar-thumb:horizontal:hover,
    & ::-webkit-scrollbar-thumb:vertical:hover,
    & ::-webkit-scrollbar-thumb:horizontal:hover {
      background-color: @scrollbar-hover-color;
    }
  }

  &__table-elm {
    display: flex;
    flex-direction: column;
    min-width: 100%;
  }

  // 表头
  &__header {
    position: relative;
    z-index: 1;
  }

  &__header-tr,
  &__tr {
    display: flex;
    min-width: 100%;
  }

  &__th,
  &__td {
    flex: 1 1 0;
    box-sizing: border-box;
    overflow: hidden;
    min-width: 0;
    border-bottom: 2rpx solid @table-border-color;
  }

  &__th {
    padding: @table-th-padding;
    background-color: @table-header-bg-color;
    color: @table-header-text-color;
    font-weight: normal;
    text-align: left;
  }

  &__td {
    padding: @table-td-padding;
    text-align: left;
  }

  &__th-content,
  &__td-content {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  // 空数据
  &__empty-row {
    display: flex;
    width: 100%;
  }

  &__empty {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    padding: @spacer-3 0;
    background-color: @bg-color-container;
    color: @text-color-placeholder;
  }

  // 表体
  &__body {
    position: relative;
    background-color: @bg-color-container;
  }

  // 表尾
  &__bottom-content {
    padding: @spacer @spacer-1;
    background-color: @bg-color-container;
    border-top: 2rpx solid @table-border-color;
  }

  // 加载中
  &__loading--full {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: @table-loading-bg-color;
    z-index: 10;
  }

  // 对齐方式
  .@{prefix}-align-left {
    text-align: left;
  }

  .@{prefix}-align-center {
    text-align: center;
  }

  .@{prefix}-align-right {
    text-align: right;
  }

  // 垂直对齐
  &.@{prefix}-vertical-align-top .@{table-prefix}__td {
    vertical-align: top;
  }

  &.@{prefix}-vertical-align-middle .@{table-prefix}__td {
    vertical-align: middle;
  }

  &.@{prefix}-vertical-align-bottom .@{table-prefix}__td {
    vertical-align: bottom;
  }

  // 边框
  &--bordered {
    border: 2rpx solid @table-border-color;

    .@{table-prefix}__th,
    .@{table-prefix}__td {
      border-right: 2rpx solid @table-border-color;

      &:last-child {
        border-right: none;
      }
    }

    .@{table-prefix}__th {
      border-bottom: 2rpx solid @table-border-color;
    }

    .@{table-prefix}__tr:last-child .@{table-prefix}__td {
      border-bottom: none;
    }
  }

  // 斑马纹（同步 mobile-vue）
  // 注意：与 mobile-vue 不同，小程序/uniapp 中表头和数据行在不同容器中，
  // __body 中的 __tr 从 1 开始计数，因此无论是否有固定表头，都用 odd 着色第1行
  &--striped {
    // 非 bordered 模式下，去掉行分割线，让斑马纹效果更纯粹
    &:not(.@{table-prefix}--bordered) {
      .@{table-prefix}__th,
      .@{table-prefix}__td {
        border-bottom: none;
      }
    }

    // 奇数行着色（第1行灰色，第2行白色...）
    .@{table-prefix}__tr:nth-child(odd) {
      background-color: @table-stripe-bg-color;

      // 固定列单元格也跟随斑马纹背景色
      .@{table-prefix}__cell--fixed-left,
      .@{table-prefix}__cell--fixed-right {
        background-color: @table-stripe-bg-color;
      }
    }
  }

  // 布局方式
  &--layout-fixed {
    .@{table-prefix}__table-elm {
      table-layout: fixed;
    }
  }

  &--layout-auto {
    .@{table-prefix}__table-elm {
      table-layout: auto;
    }
  }

  // 合并单元格：表体为 grid 布局（display 等由内联样式设置），需重置 flex 避免冲突
  &--rowspan-colspan {
    .@{table-prefix}__body {
      display: grid;
      grid-auto-rows: minmax(0, auto);
      min-width: 100%;
    }

    .@{table-prefix}__td {
      display: flex;
      align-items: center;
      flex: none;
      min-width: 0;
    }

    .@{table-prefix}__td-last-row {
      border-bottom: none;
    }

    .@{table-prefix}__td-first-col {
      border-left: none;
    }
  }

  // 合并单元格 + 边框：grid 下 :last-child 无法判断每行最后一列，
  // 改为容器画上+左边框、单元格画右+下边框，保证每条网格线只绘制一次
  &--rowspan-colspan&--bordered {
    border-right: none;
    border-bottom: none;

    .@{table-prefix}__th {
      border-right: 2rpx solid @table-border-color;
      border-bottom: 2rpx solid @table-border-color;
    }

    .@{table-prefix}__td {
      border-right: 2rpx solid @table-border-color;
      border-bottom: 2rpx solid @table-border-color;

      &:last-child {
        border-right: 2rpx solid @table-border-color;
      }
    }
  }

  // 固定表头（同步 mobile-vue：固定表头时 th 背景色为灰色）
  &__header--fixed {
    position: sticky;
    top: 0;
    z-index: 33;

    .@{table-prefix}__th {
      background-color: @bg-color-secondarycontainer;
    }
  }

  // 固定行（确保背景不透明，防止滚动时文字穿透）
  &__row--fixed-top,
  &__row--fixed-bottom {
    background-color: @bg-color-container;

    > .@{table-prefix}__td {
      background-color: @bg-color-container;
    }

    // 固定行中的固定列单元格也需要背景色
    > .@{table-prefix}__cell--fixed-left,
    > .@{table-prefix}__cell--fixed-right {
      background-color: @bg-color-container;
    }
  }

  // 斑马纹模式下固定行也需要保持背景色
  &--striped &__row--fixed-top,
  &--striped &__row--fixed-bottom {
    &:nth-child(odd) > .@{table-prefix}__td {
      background-color: @table-stripe-bg-color;
    }

    &:nth-child(even) > .@{table-prefix}__td {
      background-color: @bg-color-container;
    }

    // 固定列单元格也跟随斑马纹背景色
    &:nth-child(odd) > .@{table-prefix}__cell--fixed-left,
    &:nth-child(odd) > .@{table-prefix}__cell--fixed-right {
      background-color: @table-stripe-bg-color;
    }

    &:nth-child(even) > .@{table-prefix}__cell--fixed-left,
    &:nth-child(even) > .@{table-prefix}__cell--fixed-right {
      background-color: @bg-color-container;
    }
  }

  // 固定底部行的第一行加上边框
  &__row--fixed-bottom-first > .@{table-prefix}__td {
    border-top: 2rpx solid @table-border-color;
  }

  // 冻结表尾行时，最后一行非冻结行去除下边框
  &__row--without-border-bottom > .@{table-prefix}__td {
    border-bottom: none;
  }

  // 固定列
  &--column-fixed {
    .@{table-prefix}__cell--fixed-left,
    .@{table-prefix}__cell--fixed-right {
      position: sticky;
      z-index: @table-fixed-column-z-index;
      background-color: @bg-color-container;
    }

    .@{table-prefix}__cell--fixed-right {
      z-index: @table-fixed-column-z-index + 1;
    }

    // 固定表头中的固定列 th 需要灰色背景（覆盖固定列的白色背景，放在 column-fixed 内部确保优先级）
    .@{table-prefix}__header--fixed {
      .@{table-prefix}__cell--fixed-left,
      .@{table-prefix}__cell--fixed-right {
        background-color: @bg-color-secondarycontainer;
      }
    }

    // 右侧固定列始终显示左边框（同步 mobile-vue）
    .@{table-prefix}__cell--fixed-right-first {
      border-left: @table-fixed-cell-border-light;
    }

    // 固定列边界阴影指示器（伪元素）
    .@{table-prefix}__cell--fixed-left-last,
    .@{table-prefix}__cell--fixed-right-first {
      &::after {
        position: absolute;
        top: 0;
        bottom: 0;
        content: '';
        transition: box-shadow 0.3s;
        pointer-events: none;
        z-index: -1;
      }
    }

    .@{table-prefix}__cell--fixed-left-last::after {
      right: 0;
      transform: translateX(100%);
    }

    .@{table-prefix}__cell--fixed-right-first::after {
      left: 0;
      transform: translateX(-100%);
    }
  }

  // 可向左滚动时，左侧固定列显示阴影
  &__content--scrollable-to-left {
    .@{table-prefix}__cell--fixed-left-last::after {
      border-right: @table-fixed-cell-border-light;
    }
  }

  // 可向右滚动时，右侧固定列显示阴影
  &__content--scrollable-to-right {
    .@{table-prefix}__cell--fixed-right-first::after {
      border-left: @table-fixed-cell-border-light;
    }
  }

  // 有边框模式下的固定列阴影加粗
  &--bordered &__content--scrollable-to-left {
    .@{table-prefix}__cell--fixed-left-last::after {
      border-right: @table-fixed-cell-border;
    }
  }

  &--bordered &__content--scrollable-to-right {
    .@{table-prefix}__cell--fixed-right-first::after {
      border-left: @table-fixed-cell-border;
    }
  }
}

@import '../../../common/style/base.less';

@tabs: ~'@{prefix}-tabs';
@item: ~'@{tabs}__item';

@tab-font: var(--td-tab-font, @font-body-medium);
@tab-nav-bg-color: var(--td-tab-nav-bg-color, @bg-color-container);

@tab-item-height: var(--td-tab-item-height, 96rpx);
@tab-item-vertical-height: var(--td-tab-item-vertical-height, 108rpx);
@tab-item-vertical-width: var(--td-tab-item-vertical-width, 208rpx);

@tab-item-color: var(--td-tab-item-color, @text-color-primary);
@tab-item-active-color: var(--td-tab-item-active-color, @brand-color);
@tab-item-disabled-color: var(--td-tab-item-disabled-color, @text-color-disabled);
@tab-border-color: var(--td-tab-border-color, @component-stroke);

// track
@tab-track-color: var(--td-tab-track-color, @brand-color);
@tab-track-thickness: var(--td-tab-track-thickness, 6rpx);
@tab-track-width: var(--td-tab-track-width, 32rpx);
@tab-track-radius: var(--td-tab-track-radius, 8rpx);

// theme = tag
@tab-item-tag-height: var(--td-tab-item-tag-height, 64rpx);
@tab-item-tag-bg: var(--td-tab-item-tag-bg, @bg-color-secondarycontainer);
@tab-item-tag-active-bg: var(--td-tab-item-tag-active-bg, @brand-color-light);

@tab-icon-size: var(--td-tab-icon-size, 36rpx);

.@{prefix}-tabs {
  position: relative;
  font: @tab-font;
  background: @tab-nav-bg-color;
  flex-wrap: wrap;

  &__wrapper {
    display: flex;
    overflow: hidden;
    background: @tab-nav-bg-color;

    &--card {
      background: @tab-item-tag-bg;
      --td-tab-border-color: transparent;
    }
  }

  &__item {
    position: relative;
    display: flex;
    flex: none;
    align-items: center;
    justify-content: center;
    font-weight: 400;
    color: @tab-item-color;
    padding: 0 @spacer-2;
    box-sizing: border-box;
    white-space: nowrap;
    overflow: hidden;
    height: @tab-item-height;

    &--active {
      font-weight: 600;
      color: @tab-item-active-color;
    }

    &--disabled {
      color: @tab-item-disabled-color;
    }

    &--evenly {
      flex: 1 0 auto;
    }

    &-inner {
      display: flex;
      align-items: center;
      justify-content: center;

      &--tag {
        width: 100%;
        text-align: center;
        padding: 0 @spacer-2;
        line-height: @tab-item-tag-height;
        border-radius: calc(@tab-item-tag-height / 2);
        background-color: @tab-item-tag-bg;
      }

      &--active&--tag {
        background-color: @tab-item-tag-active-bg;
      }
    }

    &--tag:not(&--evenly) {
      padding: 0 calc(@spacer / 2);

      &:first-child {
        margin-left: @spacer;
      }

      &:last-child {
        padding-right: @spacer-1;
      }
    }

    &--tag {
      padding: 0 @spacer;
    }

    &--card {
      &.@{item}--active {
        background-color: @tab-nav-bg-color;
        border-radius: @radius-large @radius-large 0 0;

        &:first-child {
          border-top-left-radius: 0;
        }

        &:last-child {
          border-top-right-radius: 0;
        }
      }

      &.@{item}--pre {
        border-bottom-right-radius: @radius-large;
      }
    }

    &-prefix,
    &-suffix {
      position: absolute;
      bottom: 0;
      width: 18rpx;
      height: 18rpx;
      background-color: @tab-nav-bg-color;

      &::after {
        content: '';
        display: block;
        width: 100%;
        height: 100%;
        background-color: @tab-item-tag-bg;
      }
    }

    &-prefix {
      right: 0;

      &::after {
        border-bottom-right-radius: @radius-large;
      }
    }

    &-suffix {
      left: 0;

      &::after {
        border-bottom-left-radius: @radius-large;
      }
    }
  }

  &__badge {
    --td-badge-content-text-font: @tab-font;

    &--active {
      --td-badge-content-text-font: @font-mark-medium;
      --td-badge-content-text-color: @tab-item-active-color;
    }

    &--disabled {
      --td-badge-content-text-color: @tab-item-disabled-color;
    }
  }

  &__icon {
    font-size: @tab-icon-size;
    margin-right: calc(@spacer / 4);
  }

  &__content {
    overflow: hidden;
  }

  &__nav {
    position: relative;
    user-select: none;
    display: flex;
    flex-wrap: nowrap;
    align-items: center;
  }

  &__nav&__nav--evenly {
    width: 100%;
  }

  &__track {
    position: absolute;
    font-weight: 600;
    z-index: 1;
    opacity: 0;
    background-color: @tab-track-color;
    left: 0;
    bottom: 1rpx;
    width: @tab-track-width;
    height: @tab-track-thickness;
    border-radius: @tab-track-radius;
  }

  &__scroll {
    position: relative;
    height: @tab-item-height;

    &--split {
      .border(bottom, @tab-border-color);
    }

    &::-webkit-scrollbar {
      display: none;
    }
  }

  &__content {
    width: 100%;

    &-inner {
      display: block;
    }

    &--animated .@{prefix}-tabs__content-inner {
      position: relative;
      width: 100%;
      height: 100%;
      display: flex;
      will-change: left;
      transition-property: transform;
    }
  }
}

@import '../../../common/style/base.less';

// themes
@tag-default-color: var(--td-tag-default-color, @bg-color-component);
@tag-default-light-color: var(--td-tag-default-light-color, @bg-color-secondarycontainer);
@tag-primary-color: var(--td-tag-primary-color, @brand-color);
@tag-primary-light-color: var(--td-tag-primary-light-color, @brand-color-light);
@tag-success-color: var(--td-tag-success-color, @success-color);
@tag-success-light-color: var(--td-tag-success-light-color, @success-color-1);
@tag-warning-color: var(--td-tag-warning-color, @warning-color);
@tag-warning-light-color: var(--td-tag-warning-light-color, @warning-color-1);
@tag-danger-color: var(--td-tag-danger-color, @error-color);
@tag-danger-light-color: var(--td-tag-danger-light-color, @error-color-1);

// variant
@tag-outline-bg-color: var(--td-tag-outline-bg-color, @bg-color-container);
@tag-default-font-color: var(--td-tag-default-font-color, @text-color-primary);

// status
@tag-disabled-color: var(--td-tag-disabled-color, @text-color-disabled);
@tag-disabled-background-color: var(--td-tag-disabled-background-color, @bg-color-component-disabled);
@tag-disabled-border-color: var(--td-tag-disabled-border-color, @component-border);

// size
@tag-small-padding: var(--td-tag-small-padding, 2rpx 10rpx);
@tag-medium-padding: var(--td-tag-medium-padding, 2rpx 14rpx);
@tag-large-padding: var(--td-tag-large-padding, calc(@spacer / 4) 14rpx);
@tag-extra-large-padding: var(--td-tag-extra-large-padding, @spacer 30rpx);

@tag-small-font: var(--td-tag-small-font, @font-body-extraSmall);
@tag-medium-font: var(--td-tag-medium-font, @font-body-small);
@tag-large-font: var(--td-tag-large-font, @font-body-medium);
@tag-extra-large-font: var(--td-tag-extra-large-font, @font-body-medium);

@tag-small-icon-size: var(--td-tag-small-icon-size, 24rpx);
@tag-medium-icon-size: var(--td-tag-medium-icon-size, 28rpx);
@tag-large-icon-size: var(--td-tag-large-icon-size, 32rpx);
@tag-extra-large-icon-size: var(--td-tag-extra-large-icon-size, 32rpx);

@tag-square-border-radius: var(--td-tag-square-border-radius, @radius-small);
@tag-round-border-radius: var(--td-tag-round-border-radius, @radius-round);
@tag-mark-border-radius: var(--td-tag-mark-border-radius, @radius-round);

@tag-close-icon-color: var(--td-tag-close-icon-color, @text-color-placeholder);

.genVariant(@variant) {
  @themes: default, primary, success, warning, danger;
  each(@themes, {
    @theme-color: 'tag-@{value}-color';
    @theme-light-color: 'tag-@{value}-light-color';

    &.@{prefix}-tag--@{value} {
      color: if(@variant = dark, @text-color-anti, @@theme-color);
      border-color: if(@variant = light, @@theme-light-color, @@theme-color);
      background-color: if(@variant = dark, @@theme-color, @@theme-light-color);
    }
  });
}

.@{prefix}-tag {
  display: inline-flex;
  align-items: center;
  border: 2rpx solid transparent;
  box-sizing: border-box;
  border-radius: @tag-square-border-radius;
  user-select: none;
  vertical-align: middle;

  &__text {
    word-wrap: normal;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  &__icon,
  &__icon-close {
    display: flex;
    align-items: center;
  }

  &__icon-close {
    color: @tag-close-icon-color;
  }

  &__icon:not(:empty) + &__text:not(:empty),
  &__text:not(:empty) + &__icon-close:not(:empty) {
    margin-left: calc(@spacer / 2);
  }

  &.@{prefix}-tag {
    &--small {
      padding: @tag-small-padding;
      font: @tag-small-font;

      .@{prefix}-icon,
      .@{prefix}-icon-close {
        font-size: @tag-small-icon-size;
      }

      .@{prefix}-tag__icon:not(:empty) + .@{prefix}-tag__text:not(:empty),
      .@{prefix}-tag__text:not(:empty) + .@{prefix}-tag__icon-close:not(:empty) {
        margin-left: calc(@spacer / 4);
      }
    }

    &--medium {
      padding: @tag-medium-padding;
      font: @tag-medium-font;

      .@{prefix}-icon,
      .@{prefix}-icon-close {
        font-size: @tag-medium-icon-size;
      }
    }

    &--large {
      padding: @tag-large-padding;
      font: @tag-large-font;

      .@{prefix}-icon,
      .@{prefix}-icon-close {
        font-size: @tag-large-icon-size;
      }
    }

    &--extra-large {
      padding: @tag-extra-large-padding;
      font: @tag-extra-large-font;

      .@{prefix}-icon,
      .@{prefix}-icon-close {
        font-size: @tag-extra-large-icon-size;
      }
    }
  }

  &.@{prefix}-tag {
    &--square {
      border-radius: @tag-square-border-radius;

      &.@{prefix}-tag--extra-large {
        border-radius: calc(@tag-square-border-radius * 2);
      }
    }

    &--round {
      border-radius: @tag-round-border-radius;
    }

    &--mark {
      border-radius: 0;
      border-top-right-radius: @tag-mark-border-radius;
      border-bottom-right-radius: @tag-mark-border-radius;
    }
  }

  &--dark {
    .genVariant(dark);
    &.@{prefix}-tag--default {
      color: @tag-default-font-color;
    }
  }

  &--outline {
    .genVariant(outline);
    &.@{prefix}-tag--default {
      color: @tag-default-font-color;
    }
    each(@themes, {
      &.@{prefix}-tag--@{value} {
        background-color: @tag-outline-bg-color;
      }
    });
  }

  &--light {
    .genVariant(light);
    &.@{prefix}-tag--default {
      color: @tag-default-font-color;
    }
  }

  &--light-outline {
    .genVariant(light-outline);
    &.@{prefix}-tag--default {
      color: @tag-default-font-color;
      border-color: @component-border;
    }
  }

  &.@{prefix}-tag--closable {
    &.@{prefix}-tag--disabled {
      cursor: not-allowed;
      color: @tag-disabled-color;
      background-color: @tag-disabled-background-color;
      border-color: @tag-disabled-border-color;
    }
  }
}

@import '../../../common/style/base.less';

@toast-color: var(--td-toast-color, @text-color-anti);
@toast-bg-color: var(--td-toast-bg-color, @mask-active);
@toast-max-width: var(--td-toast-max-width, 370rpx);
@toast-radius: var(--td-toast-radius, @radius-default);
@toast-row-icon-size: var(--td-toast-row-icon-size, 48rpx);
@toast-column-icon-size: var(--td-toast-column-icon-size, 64rpx);

.@{prefix}-toast {
  position: fixed;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: @z-index-toast;
  opacity: 1;
  transition: opacity 300ms ease;
  background-color: @toast-bg-color;
  border-radius: @toast-radius;
  color: @toast-color;
  max-width: @toast-max-width;
  min-height: 0; // 防止 flex 容器被意外拉伸
  width: auto;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  box-sizing: border-box;

  &--column {
    padding: @spacer-3;
    min-width: 160rpx;
    min-height: 160rpx;
    border-radius: 16rpx;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  &--loading&--with-text {
    min-width: 204rpx;
    min-height: 204rpx;
    padding-top: 0;
    padding-bottom: 0;
  }

  &__content {
    align-items: center;
    font: @font-body-medium;

    &--row {
      display: flex;
      text-align: left;
      padding: 28rpx 44rpx;
    }

    &--column {
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
    }
  }

  &__icon {
    &--row {
      display: flex;
      font-size: @toast-row-icon-size;
    }
    &--column {
      font-size: @toast-column-icon-size;
    }
  }

  &__text {
    overflow: hidden;
    text-overflow: ellipsis;
    -webkit-line-clamp: 3;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    white-space: pre-line;

    &--column:not(:empty):not(:only-child) {
      margin-top: @spacer;
    }

    &--row:not(:empty):not(:only-child) {
      margin-left: @spacer;
    }
  }

  &.@{prefix}-fade-enter,
  &.@{prefix}-fade-leave-to {
    opacity: 0;
  }
}

@import '../../../common/style/base.less';

@tree-bg-color: var(--td-tree-bg-color, @bg-color-container);
@tree-root-bg-color: var(--td-tree-root-bg-color, @bg-color-secondarycontainer);
@tree-item-active-color: var(--td-tree-item-active-color, @brand-color);
@tree-item-disabled-color: var(--td-tree-item-disabled-color, @text-color-disabled);
@tree-item-height: var(--td-tree-item-height, 112rpx);
@tree-item-font-size: var(--td-tree-item-font-size, @font-size-m);
@tree-colum-width: var(--td-tree-colum-width, 206rpx);
@tree-colum-text-color: var(--td-tree-colum-text-color, @text-color-primary);

.@{prefix}-tree-select {
  display: flex;
  background-color: @tree-bg-color;

  &__column {
    width: @tree-colum-width;
    color: @tree-colum-text-color;

    &--left {
      background: @tree-root-bg-color;
    }

    &--right {
      flex: 1;
    }

    &::-webkit-scrollbar {
      display: none;
      width: 0;
      height: 0;
      color: transparent;
    }
  }

  &__item {
    .ellipsisLn(1);

    height: @tree-item-height;
    line-height: @tree-item-height;
    font-size: @tree-item-font-size;
    padding-left: @spacer-2;

    &--active {
      font-weight: 600;
      color: @tree-item-active-color;
    }

    &--disabled {
      pointer-events: none;
      cursor: not-allowed;
      color: @tree-item-disabled-color;
    }
  }

  &-column {
    width: 100%;
    height: auto;
  }
}
